-- V28 FOUNDATION ONLY. Same existing Finance360 MySQL schema. No financial tables created or altered.
-- Run using the CLI migrator against a reviewed staging clone first. MySQL DDL is not transactional.
CREATE TABLE IF NOT EXISTS f28_schema (version INT PRIMARY KEY, applied_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, verified_at DATETIME NULL, disabled_at DATETIME NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, term_months TINYINT UNSIGNED NOT NULL, price_paise BIGINT UNSIGNED NULL, branch_limit INT UNSIGNED NOT NULL, user_limit INT UNSIGNED NOT NULL, features_json TEXT NOT NULL, available TINYINT NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, CHECK(term_months IN (1,3,6,12)), CHECK(branch_limit>0), CHECK(user_limit>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_tenants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, address VARCHAR(500) NOT NULL, city VARCHAR(100) NOT NULL, timezone VARCHAR(60) NOT NULL DEFAULT 'Asia/Kolkata', currency CHAR(3) NOT NULL DEFAULT 'INR', language VARCHAR(5) NOT NULL DEFAULT 'en', logo_key VARCHAR(190) NULL, financial_scope_state VARCHAR(20) NOT NULL DEFAULT 'blocked', created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_branches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, address VARCHAR(500) NOT NULL, cutoff_hour TINYINT UNSIGNED NOT NULL DEFAULT 4, active TINYINT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, UNIQUE KEY uq_f28_branch_scope(tenant_id,id), CONSTRAINT f28_branch_tenant FOREIGN KEY(tenant_id) REFERENCES f28_tenants(id), CHECK(cutoff_hour<24)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_memberships (tenant_id BIGINT UNSIGNED NOT NULL, account_id BIGINT UNSIGNED NOT NULL, role VARCHAR(30) NOT NULL, grants_json TEXT NOT NULL, denies_json TEXT NOT NULL, revision BIGINT NOT NULL DEFAULT 1, active TINYINT NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,account_id), FOREIGN KEY(tenant_id) REFERENCES f28_tenants(id), FOREIGN KEY(account_id) REFERENCES f28_accounts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_branch_memberships (tenant_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED NOT NULL, account_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(tenant_id,branch_id,account_id), FOREIGN KEY(tenant_id,branch_id) REFERENCES f28_branches(tenant_id,id), FOREIGN KEY(tenant_id,account_id) REFERENCES f28_memberships(tenant_id,account_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_subscriptions (tenant_id BIGINT UNSIGNED PRIMARY KEY, state VARCHAR(20) NOT NULL, trial_started_at DATETIME NOT NULL, trial_ends_at DATETIME NOT NULL, paid_until DATETIME NULL, grace_until DATETIME NULL, branch_limit INT UNSIGNED NOT NULL DEFAULT 1, user_limit INT UNSIGNED NOT NULL DEFAULT 5, plan_id BIGINT UNSIGNED NULL, version BIGINT NOT NULL DEFAULT 1, FOREIGN KEY(tenant_id) REFERENCES f28_tenants(id), FOREIGN KEY(plan_id) REFERENCES f28_plans(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_sessions (id CHAR(32) PRIMARY KEY, account_id BIGINT UNSIGNED NOT NULL, revoked_at DATETIME NULL, created_at DATETIME NOT NULL, FOREIGN KEY(account_id) REFERENCES f28_accounts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_tokens (token_hash CHAR(64) PRIMARY KEY, session_id CHAR(32) NOT NULL, kind VARCHAR(10) NOT NULL, expires_at DATETIME NOT NULL, consumed_at DATETIME NULL, created_at DATETIME NOT NULL, FOREIGN KEY(session_id) REFERENCES f28_sessions(id), INDEX f28_tokens_session(session_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_rate_limits (bucket CHAR(64) PRIMARY KEY, attempts INT NOT NULL, window_start BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NULL, account_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, detail_json TEXT NOT NULL, created_at DATETIME NOT NULL, INDEX f28_audit_scope(tenant_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_consents (account_id BIGINT UNSIGNED NOT NULL, purpose VARCHAR(40) NOT NULL, policy_version VARCHAR(30) NOT NULL, accepted_at DATETIME NOT NULL, PRIMARY KEY(account_id,purpose,policy_version), FOREIGN KEY(account_id) REFERENCES f28_accounts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_deletion_requests (account_id BIGINT UNSIGNED PRIMARY KEY, requested_at DATETIME NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'requested', FOREIGN KEY(account_id) REFERENCES f28_accounts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_platform_admins (account_id BIGINT UNSIGNED PRIMARY KEY, totp_secret_enc TEXT NOT NULL, last_counter BIGINT NOT NULL DEFAULT -1, active TINYINT NOT NULL DEFAULT 1, FOREIGN KEY(account_id) REFERENCES f28_accounts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS f28_stepups (session_id CHAR(32) PRIMARY KEY, expires_at DATETIME NOT NULL, FOREIGN KEY(session_id) REFERENCES f28_sessions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
